<script setup lang="ts">
import { vModalFocus } from '@go-admin-plus/ui'
import { CalendarClockIcon, CheckCircle2Icon, ChevronRightIcon, Clock3Icon, HistoryIcon, PencilIcon, PlayIcon, PlusIcon, RefreshCwIcon, Trash2Icon, XCircleIcon } from '@lucide/vue'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import type { Definition, DefinitionInput, ExecutionStatus, ParameterField, TaskType } from '@go-admin-plus/domain-scheduler'
import { settleSchedulerPageOperation, type SchedulerController } from './scheduler-controller'
import { schedulerViewForPath } from './scheduler-view'

const props = defineProps<{ controller: SchedulerController }>()
const emit = defineEmits<{ sessionRequired: [] }>()
const route = useRoute()
const view = computed(() => schedulerViewForPath(route.path))
const revision = ref(0)
const search = ref('')
const formOpen = ref(false)
const scheduleMode = ref<'preset' | 'custom'>('preset')
const preset = ref('daily')
const executionFilters = reactive<{ definitionId: string; status: ExecutionStatus | '' }>({ definitionId: '', status: '' })
const edited = ref<Definition | null>(null)
const form = reactive({ name: '', taskType: '', cron: '0 9 * * *', timezone: 'Asia/Shanghai', parameters: {} as Record<string, string | number | boolean> })
const definitions = computed(() => { void revision.value; return props.controller.definitions.snapshot() })
const executions = computed(() => { void revision.value; return props.controller.executions.snapshot() })
const taskTypes = computed(() => { void revision.value; return props.controller.taskTypes() })
const selectedTask = computed<TaskType | undefined>(() => taskTypes.value.find(value => value.key === form.taskType))
const blocked = computed(() => { void revision.value; return props.controller.busy || props.controller.hasPendingRepair() })
const can = (permission: string) => { void revision.value; return props.controller.can(permission) }
const failureMessage = computed(() => { void revision.value; const value = props.controller.failure(); if (value === 'relogin') return '会话已失效，请重新登录。'; if (value === 'forbidden') return '没有执行该操作的权限。'; if (value === 'validation') return '请检查任务名称、计划和参数。'; if (value === 'not-found') return '任务定义已不存在。'; if (value === 'conflict') return '任务定义已发生变化，请刷新后重试。'; if (value === 'unavailable') return '调度服务暂不可用。'; return '' })
const failureReference = computed(() => { void revision.value; return props.controller.failureTraceId() })
const run = (operation: () => Promise<unknown>) => settleSchedulerPageOperation(operation, () => { if (props.controller.failure() === 'relogin') emit('sessionRequired'); revision.value += 1 })
const scheduleForPreset = (value: string) => ({ cron: ({ 'every-minute': '* * * * *', hourly: '0 * * * *', weekdays: '0 9 * * 1-5', weekly: '0 9 * * 1', monthly: '0 9 1 * *', daily: '0 9 * * *' } as Record<string, string>)[value] ?? '0 9 * * *', timezone: form.timezone })
const request = (): DefinitionInput => ({ name: form.name.trim(), taskType: form.taskType, schedule: scheduleMode.value === 'preset' ? scheduleForPreset(preset.value) : { cron: form.cron, timezone: form.timezone }, parameters: { ...form.parameters } })
const initializeParameters = (task: TaskType | undefined) => { const next: Record<string, string | number | boolean> = {}; for (const field of task?.fields ?? []) next[field.name] = field.kind === 'boolean' ? false : field.kind === 'integer' ? field.minimum ?? 0 : field.allowedValues?.[0] ?? ''; form.parameters = next }
const resetForm = () => { const task = props.controller.taskTypes()[0]; edited.value = null; form.name = ''; form.taskType = task?.key ?? ''; scheduleMode.value = 'preset'; preset.value = 'daily'; form.cron = '0 9 * * *'; form.timezone = 'Asia/Shanghai'; initializeParameters(task) }
const closeForm = () => { formOpen.value = false; resetForm() }
const create = () => { resetForm(); formOpen.value = true }
watch(() => form.taskType, () => { if (!edited.value || edited.value.taskType !== form.taskType) initializeParameters(selectedTask.value) })
const edit = (value: Definition) => { edited.value = value; form.name = value.name; form.taskType = value.taskType; scheduleMode.value = 'custom'; form.cron = value.schedule.cron; form.timezone = value.schedule.timezone; form.parameters = { ...value.parameters }; formOpen.value = true }
const submit = () => run(async () => { const result = edited.value ? await props.controller.updateDefinition(edited.value, request()) : await props.controller.createDefinition(request()); if (result === 'completed') closeForm() })
const searchDefinitions = () => run(() => props.controller.definitions.search({ search: search.value }))
const searchExecutions = () => run(() => props.controller.executions.search({ ...executionFilters }))
const numberValue = (field: ParameterField) => ({ min: field.minimum, max: field.maximum })
const formatDate = (value: string | null | undefined) => value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '未安排'
const taskTypeLabel = (key: string) => taskTypes.value.find(value => value.key === key)?.label ?? key
const executionStatusLabel = (value: ExecutionStatus) => value === 'succeeded' ? '成功' : '失败'
const scheduleLabel = (value: Definition) => `${value.schedule.cron} · ${value.schedule.timezone}`
const presetOptions = [
  { value: 'every-minute', label: '每分钟', hint: '高频检查' }, { value: 'hourly', label: '每小时', hint: '整点执行' }, { value: 'daily', label: '每天', hint: '每天 09:00' },
  { value: 'weekdays', label: '工作日', hint: '周一至周五' }, { value: 'weekly', label: '每周', hint: '每周一' }, { value: 'monthly', label: '每月', hint: '每月 1 日' }
]
const loadView = () => run(async () => { if (view.value === 'definitions' && can('scheduler.definitions.read')) { await props.controller.refreshTaskTypes(); resetForm(); await props.controller.definitions.refresh() }; if (view.value === 'executions' && can('scheduler.executions.read')) await props.controller.executions.refresh() })
onMounted(loadView)
watch(view, () => { closeForm(); void loadView() })
</script>

<template>
  <main class="scheduler-page ga-work-page">
    <header class="scheduler-hero"><div><p class="eyebrow">WORKFLOWS / LOCAL CRON</p><h1>任务调度</h1><p class="hero-description">集中管理本地任务计划，清晰查看运行状态与执行结果。</p></div><div class="hero-mark" aria-hidden="true"><CalendarClockIcon :size="28" /></div></header>
    <p v-if="failureMessage" class="scheduler-alert" role="alert">{{ failureMessage }}<span v-if="failureReference"> 参考编号：{{ failureReference }}</span></p>
    <button v-if="controller.hasPendingRepair()" class="repair-banner" type="button" data-testid="repair-scheduler" :disabled="controller.busy" @click="run(() => controller.repairProjection())"><RefreshCwIcon :size="16" />刷新已保存的变更<ChevronRightIcon :size="16" /></button>
    <nav class="scheduler-tabs" aria-label="任务调度视图"><RouterLink to="/scheduler/definitions" :class="{ active: view === 'definitions' }"><CalendarClockIcon :size="16" />任务定义</RouterLink><RouterLink to="/scheduler/executions" :class="{ active: view === 'executions' }"><HistoryIcon :size="16" />执行记录</RouterLink></nav>
    <section v-if="view === 'definitions' && can('scheduler.definitions.read')" class="scheduler-surface">
      <div class="surface-toolbar"><form class="search-form" @submit.prevent="searchDefinitions"><label class="sr-only" for="scheduler-search">搜索任务</label><div class="search-input"><span aria-hidden="true">⌕</span><input id="scheduler-search" v-model.trim="search" maxlength="100" placeholder="搜索任务名称"></div><button type="submit" class="button button--secondary" :disabled="blocked">搜索</button><button type="button" class="button button--ghost" :disabled="blocked || !search" @click="search = ''; run(() => controller.definitions.reset())">重置</button></form><button v-if="can('scheduler.definitions.write')" type="button" class="button button--primary" data-testid="open-scheduler-definition-form" :disabled="blocked" @click="create"><PlusIcon :size="16" />新增任务</button></div>
      <div v-if="definitions.rows.length" class="definition-list"><article v-for="item in definitions.rows" :key="item.id" class="definition-row" :data-row-key="item.id"><div class="definition-icon"><Clock3Icon :size="18" /></div><div class="definition-main"><strong>{{ item.name }}</strong><span>{{ taskTypeLabel(item.taskType) }} · {{ scheduleLabel(item) }}</span><small>下一次执行：{{ formatDate(item.nextRunAt) }}</small></div><span class="status-pill" :class="item.enabled ? 'is-running' : 'is-stopped'"><span></span>{{ item.enabled ? '运行中' : '已停止' }}</span><div class="definition-actions"><button v-if="can('scheduler.definitions.write')" type="button" :disabled="blocked" @click="run(() => controller.runDefinition(item))">执行一次</button><button v-if="can('scheduler.definitions.write')" type="button" class="icon-button" data-action="edit" :disabled="item.enabled || blocked" title="修改任务" @click="edit(item)"><PencilIcon :size="16" /></button><button v-if="can('scheduler.definitions.write')" type="button" class="icon-button" data-action="toggle" :disabled="blocked" :title="item.enabled ? '停止任务' : '启用任务'" @click="run(() => item.enabled ? controller.stopDefinition(item) : controller.enableDefinition(item))"><XCircleIcon v-if="item.enabled" :size="16" /><PlayIcon v-else :size="16" /></button><button v-if="can('scheduler.definitions.delete')" type="button" class="icon-button icon-button--danger" data-action="delete" :disabled="blocked" title="删除任务" @click="run(() => controller.deleteDefinition(item))"><Trash2Icon :size="16" /></button></div></article></div><EmptyState v-else title="暂无任务定义" description="创建一个任务计划后，它会显示在这里。" />
      <div class="list-footer" data-testid="scheduler-definitions-pagination"><span>共 {{ definitions.total }} 条任务</span><div class="pagination"><button type="button" :disabled="blocked || definitions.page <= 1" @click="run(() => controller.definitions.setPage(definitions.page - 1))">上一页</button><span>第 {{ definitions.page }} 页</span><label>每页<select :value="definitions.pageSize" :disabled="blocked" @change="run(() => controller.definitions.setPageSize(Number(($event.target as HTMLSelectElement).value)))"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option></select></label><button type="button" :disabled="blocked || definitions.page * definitions.pageSize >= definitions.total" @click="run(() => controller.definitions.setPage(definitions.page + 1))">下一页</button></div></div>
      <div v-if="formOpen && can('scheduler.definitions.write')" class="management-dialog-backdrop" @click.self="closeForm" @keydown.esc="closeForm"><form class="management-dialog management-dialog--wide scheduler-definition-form" data-testid="scheduler-definition-form" role="dialog" v-modal-focus aria-modal="true" aria-labelledby="scheduler-definition-title" @submit.prevent="submit"><header class="management-dialog__header"><div><p class="eyebrow">TASK BUILDER</p><h2 id="scheduler-definition-title">{{ edited ? '修改任务' : '新增任务' }}</h2></div><button type="button" aria-label="关闭" class="icon-button" @click="closeForm">×</button></header><div class="management-dialog__body"><div class="form-grid"><label>任务名称<input name="name" v-model.trim="form.name" autofocus required maxlength="100" placeholder="例如：定期清理审计"></label><label>任务类型<select name="taskType" v-model="form.taskType" required :disabled="Boolean(edited)"><option disabled value="">请选择任务类型</option><option v-for="task in taskTypes" :key="task.key" :value="task.key">{{ task.label }}</option></select></label></div><fieldset class="schedule-builder"><legend>执行计划 <span>按所选时区计算</span></legend><div class="mode-switch" role="tablist" aria-label="计划模式"><button type="button" role="tab" :aria-selected="scheduleMode === 'preset'" :class="{ active: scheduleMode === 'preset' }" @click="scheduleMode = 'preset'">常用计划</button><button type="button" role="tab" :aria-selected="scheduleMode === 'custom'" :class="{ active: scheduleMode === 'custom' }" @click="scheduleMode = 'custom'">自定义计划</button></div><div v-if="scheduleMode === 'preset'" class="preset-grid"><button v-for="option in presetOptions" :key="option.value" type="button" class="preset-card" :class="{ active: preset === option.value }" :aria-pressed="preset === option.value" @click="preset = option.value"><span>{{ option.label }}</span><small>{{ option.hint }}</small><CheckCircle2Icon v-if="preset === option.value" :size="16" /></button></div><div v-else class="custom-schedule-grid"><label>Cron 表达式<input name="cron" v-model.trim="form.cron" required maxlength="256" placeholder="0 9 * * *"></label><p class="field-help">依次为分钟、小时、日期、月份、星期。</p></div><label>时区<input name="timezone" v-model.trim="form.timezone" required placeholder="Asia/Shanghai"></label><p class="schedule-preview"><Clock3Icon :size="16" />{{ scheduleMode === 'preset' ? (presetOptions.find(option => option.value === preset)?.label + ' · ' + presetOptions.find(option => option.value === preset)?.hint) : '自定义时间 · 保存后计算下一次执行' }}</p></fieldset><fieldset v-if="selectedTask" class="parameter-builder" data-testid="scheduler-parameters"><legend>任务参数</legend><div class="form-grid"><label v-for="field in selectedTask.fields" :key="field.name">{{ field.label }}<select v-if="field.allowedValues" :name="field.name" v-model="form.parameters[field.name]" :required="field.required"><option v-for="value in field.allowedValues" :key="value" :value="value">{{ value }}</option></select><input v-else-if="field.kind === 'integer'" :name="field.name" v-model.number="form.parameters[field.name]" type="number" :min="numberValue(field).min" :max="numberValue(field).max" :required="field.required"><label v-else-if="field.kind === 'boolean'" class="checkbox-field"><input :name="field.name" v-model="form.parameters[field.name]" type="checkbox">启用</label><input v-else :name="field.name" v-model="form.parameters[field.name]" maxlength="256" :required="field.required"></label></div></fieldset></div><footer class="management-dialog__footer"><button type="button" class="button button--ghost" @click="closeForm">取消</button><button type="submit" class="button button--primary" :disabled="blocked"><CheckCircle2Icon :size="16" />保存任务</button></footer></form></div>
    </section>
     <section v-else-if="view === 'executions' && can('scheduler.executions.read')" class="scheduler-surface"><div class="surface-heading"><div><h2>执行记录</h2><p>追踪每次任务执行的结果、耗时和错误码。</p></div><button type="button" class="button button--ghost" :disabled="blocked" @click="run(() => controller.executions.refresh())"><RefreshCwIcon :size="16" />刷新</button></div><form class="execution-filters" @submit.prevent="searchExecutions"><label>任务 ID<input v-model.trim="executionFilters.definitionId" placeholder="粘贴任务 ID"></label><label>执行状态<select v-model="executionFilters.status"><option value="">全部状态</option><option value="succeeded">成功</option><option value="failed">失败</option></select></label><button type="submit" class="button button--secondary" :disabled="blocked">筛选</button></form><div class="execution-table-wrap"><table class="execution-table"><thead><tr><th>开始时间</th><th>任务类型</th><th>状态</th><th>计划时间</th><th>错误码</th><th>执行器</th></tr></thead><tbody><tr v-for="item in executions.rows" :key="item.id"><td>{{ formatDate(item.startedAt) }}</td><td>{{ taskTypeLabel(item.taskType) }}</td><td><span class="status-pill" :class="item.status === 'succeeded' ? 'is-running' : 'is-failed'"><span></span>{{ executionStatusLabel(item.status) }}</span></td><td>{{ formatDate(item.scheduledFor) }}</td><td><code>{{ item.errorCode || '—' }}</code></td><td>{{ item.executorOwner }}</td></tr></tbody></table><EmptyState v-if="!executions.rows.length" title="暂无执行记录" description="任务执行后，结果会出现在这里。" /></div><div class="list-footer" data-testid="scheduler-executions-pagination"><span>共 {{ executions.total }} 条记录</span><div class="pagination"><button type="button" :disabled="blocked || executions.page <= 1" @click="run(() => controller.executions.setPage(executions.page - 1))">上一页</button><span>第 {{ executions.page }} 页</span><label>每页<select :value="executions.pageSize" :disabled="blocked" @change="run(() => controller.executions.setPageSize(Number(($event.target as HTMLSelectElement).value)))"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option></select></label><button type="button" :disabled="blocked || executions.page * executions.pageSize >= executions.total" @click="run(() => controller.executions.setPage(executions.page + 1))">下一页</button></div></div></section>
    <section v-else class="scheduler-empty"><CalendarClockIcon :size="32" /><h2>当前没有可访问的任务调度视图</h2><p>请联系管理员申请对应的调度权限。</p></section>
  </main>
</template>

<style scoped>
.scheduler-page{display:grid;gap:16px;color:var(--ga-text-1)}.scheduler-hero{display:flex;align-items:center;justify-content:space-between;padding:8px 2px 4px}.scheduler-hero h1{margin:2px 0 5px;font-size:26px;letter-spacing:0}.eyebrow{margin:0;color:var(--ga-brand);font-size:11px;font-weight:700;letter-spacing:.08em}.hero-description,.surface-heading p{margin:0;color:var(--ga-text-3);font-size:13px}.hero-mark{display:grid;width:52px;height:52px;place-items:center;color:var(--ga-brand);background:var(--ga-brand-soft);border:1px solid var(--ga-border-light);border-radius:14px}.scheduler-alert{margin:0;padding:10px 12px;color:var(--ga-danger);background:var(--ga-danger-soft);border:1px solid color-mix(in srgb,var(--ga-danger) 18%,transparent);border-radius:var(--ga-radius)}.repair-banner{display:flex;align-items:center;gap:7px;width:100%;padding:10px 12px;color:var(--ga-brand);background:var(--ga-brand-soft);border:1px solid color-mix(in srgb,var(--ga-brand) 20%,transparent);border-radius:var(--ga-radius);cursor:pointer}.repair-banner svg:last-child{margin-left:auto}.scheduler-tabs{display:flex;gap:4px;border-bottom:1px solid var(--ga-border-light)}.scheduler-tabs a{display:flex;align-items:center;gap:7px;padding:10px 14px;color:var(--ga-text-3);border-bottom:2px solid transparent;text-decoration:none;font-size:13px}.scheduler-tabs a:hover,.scheduler-tabs a.active{color:var(--ga-brand);border-bottom-color:var(--ga-brand)}.scheduler-surface{display:grid;gap:16px;padding:18px;background:var(--ga-bg-container);border:1px solid var(--ga-border-light);border-radius:var(--ga-radius-lg);box-shadow:var(--ga-shadow-sm)}.surface-toolbar,.surface-heading,.list-footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.surface-heading h2{margin:0 0 4px;font-size:18px}.search-form,.execution-filters{display:flex;align-items:end;gap:8px;flex-wrap:wrap}.search-input{display:flex;align-items:center;gap:7px;min-width:220px;padding:0 10px;background:var(--ga-bg-subt